ActualData.Energy.APenergyAH := UDINT_TO_REAL(Ap3131Data.Energy.APenergyAH)/10;
ActualData.Energy.APenergyBH := UDINT_TO_REAL(Ap3131Data.Energy.APenergyBH)/10;
ActualData.Energy.APenergyCH := UDINT_TO_REAL(Ap3131Data.Energy.APenergyCH)/10;
ActualData.Energy.ANenergyTH := UDINT_TO_REAL(Ap3131Data.Energy.ANenergyTH)/10;
ActualData.Energy.ANenergyAH := UDINT_TO_REAL(Ap3131Data.Energy.ANenergyAH)/10;
ActualData.Energy.ANenergyBH := UDINT_TO_REAL(Ap3131Data.Energy.ANenergyBH)/10;
ActualData.Energy.ANenergyCH := UDINT_TO_REAL(Ap3131Data.Energy.ANenergyCH)/10;
ActualData.Energy.AEnergyT   := DINT_TO_REAL(Ap3131Data.Energy.AEnergyT)*10;
ActualData.Energy.REnergyT   := DINT_TO_REAL(Ap3131Data.Energy.REnergyT)*10;
ActualData.Dft.DftAI_Fund    := Ap3131Data.Dft.DftAI_Fund;
ActualData.Dft.DftBI_Fund    := Ap3131Data.Dft.DftBI_Fund;
ActualData.Dft.DftCI_Fund    := Ap3131Data.Dft.DftCI_Fund;
ActualData.Dft.DftAV_Fund    := Ap3131Data.Dft.DftAV_Fund;
ActualData.Dft.DftBV_Fund    := Ap3131Data.Dft.DftBV_Fund;
ActualData.Dft.DftCV_Fund    := Ap3131Data.Dft.DftCV_Fund;
ActualData.CfgActual         := Ap3131Data.CfgActual;
ActualData.NetTimeEnergy     := Ap3131Data.NetTimeEnergy;

IF(Actual_Energy_Total >= 400000) AND (MACHINE_STATUS = 2)AND (NOT gFl_Energy_Clear)THEN
Shift_Change_Temp_1 := MC_SHIFT_REPORT.INPUT_PARAMETERS[85];
Shift_Change_Temp_2 := MC_SHIFT_REPORT.INPUT_PARAMETERS[89];
Shift_Change_Temp_3 := MC_SHIFT_REPORT.INPUT_PARAMETERS[90];
CUMMU_ENERGY 			:= 0;
CUMMU_APP_ENERGY 		:= 0;
CUMMU_REAC_ENERGY 		:= 0;
gFl_Energy_Clear 		:= 1;
ELSE
IF NOT HMI_ENERGY_RESET THEN
gFl_Energy_Clear := 0;
END_IF
END_IF

ACTIVE_POWER_PhaseA 		:= INT_TO_REAL(ActualData.Power.PmeanA) /1000;
ACTIVE_POWER_PhaseB			:= INT_TO_REAL(ActualData.Power.PmeanB) /1000;
ACTIVE_POWER_PhaseC			:= INT_TO_REAL(ActualData.Power.PmeanC) /1000;
ACTIVE_POWER_Total			:= DINT_TO_REAL(ActualData.Power.PmeanT) /1000;
APPARENT_POWER_Total 		:= DINT_TO_REAL (ActualData.Power.SAmeanT) / 1000;
Reacrive_Power				:=SQRT(DINT_TO_REAL((ActualData.Power.SAmeanT*ActualData.Power.SAmeanT)-(ActualData.Power.PmeanT *ActualData.Power.PmeanT )));
REACTIVE_POWER_Total		:= Reacrive_Power /1000;
Actual_Energy_Total			:= ActualData.Energy.AEnergyT/3600.0;
APPARENT_Energy_Total		:= (ActualData.Energy.SAenergyT/3600.0)*100;
Reactive_Energy				:= SQRT((APPARENT_Energy_Total*APPARENT_Energy_Total)-(Actual_Energy_Total *Actual_Energy_Total));
REACTIVE_Energy_Total		:= Reactive_Energy;
Voltage_avg 				:= (ActualData.Rms.UrmsA + ActualData.Rms.UrmsB + ActualData.Rms.UrmsC) / 3;
Current_avg 				:= (ActualData.Rms.IrmsA + ActualData.Rms.IrmsB + ActualData.Rms.IrmsC) / 3;

CASE Doffer_Step OF
1:
IF  M2000 THEN Doffer_Step_1_time(START := TRUE); ELSIF  M1425 THEN	Doffer_Step := 2; END_IF
2:
IF  M1425 THEN Doffer_Step_2_time(START := TRUE); ELSIF  M1413 THEN	Doffer_Step := 3; END_IF
3:
IF  M1413 THEN Doffer_Step_3_time(START := TRUE); ELSIF  M1423 THEN	Doffer_Step := 4; END_IF
4:
IF  M1423 THEN Doffer_Step_4_time(START := TRUE); ELSIF  M1412 THEN	Doffer_Step := 5; END_IF
5:
IF  M1412 THEN Doffer_Step_5_time(START := TRUE); ELSIF  M1426 THEN	Doffer_Step := 6; END_IF
6:
IF  M1426 THEN Doffer_Step_6_time(START := TRUE); ELSIF  M1414 THEN	Doffer_Step := 7; END_IF
7:
IF  M1414 THEN Doffer_Step_7_time(START := TRUE); ELSIF  M1426 THEN	Doffer_Step := 8; END_IF
8:
IF  M1426 THEN Doffer_Step_8_time(START := TRUE); ELSIF  NOT M1414 THEN	Doffer_Step := 9; END_IF
9:
IF  NOT M1414 THEN Doffer_Step_9_time(START := TRUE); ELSIF  M1414 THEN	Doffer_Step := 10; END_IF
10:
DOFF_REPORT1[31] := ((Doffer_Step_1_time.MINUTES * 60) + (Doffer_Step_1_time.SECONDS));
DOFF_REPORT1[32] := ((Doffer_Step_2_time.MINUTES * 60) + (Doffer_Step_2_time.SECONDS));
DOFF_REPORT1[33] := ((Doffer_Step_3_time.MINUTES * 60) + (Doffer_Step_3_time.SECONDS));
DOFF_REPORT1[34] := ((Doffer_Step_4_time.MINUTES * 60) + (Doffer_Step_4_time.SECONDS));
DOFF_REPORT1[35] := ((Doffer_Step_5_time.MINUTES * 60) + (Doffer_Step_5_time.SECONDS));
DOFF_REPORT1[36] := ((Doffer_Step_6_time.MINUTES * 60) + (Doffer_Step_6_time.SECONDS));
DOFF_REPORT1[37] := ((Doffer_Step_7_time.MINUTES * 60) + (Doffer_Step_7_time.SECONDS));
DOFF_REPORT1[38] := ((Doffer_Step_8_time.MINUTES * 60) + (Doffer_Step_8_time.SECONDS));
DOFF_REPORT1[39] := ((Doffer_Step_9_time.MINUTES * 60) + (Doffer_Step_9_time.SECONDS));
Doffer_Step := 11;
11:
Doffer_Step_1_time(START := FALSE,RESET := TRUE);
Doffer_Step_2_time(START := FALSE,RESET := TRUE);
Doffer_Step_3_time(START := FALSE,RESET := TRUE);
Doffer_Step_4_time(START := FALSE,RESET := TRUE);
Doffer_Step_5_time(START := FALSE,RESET := TRUE);
Doffer_Step_6_time(START := FALSE,RESET := TRUE);
Doffer_Step_7_time(START := FALSE,RESET := TRUE);
Doffer_Step_8_time(START := FALSE,RESET := TRUE);
Doffer_Step_9_time(START := FALSE,RESET := TRUE);
Doffer_Step := 12;
12:
Doffer_Step_1_time(RESET := FALSE);
Doffer_Step_2_time(RESET := FALSE);
Doffer_Step_3_time(RESET := FALSE);
Doffer_Step_4_time(RESET := FALSE);
Doffer_Step_5_time(RESET := FALSE);
Doffer_Step_6_time(RESET := FALSE);
Doffer_Step_7_time(RESET := FALSE);
Doffer_Step_8_time(RESET := FALSE);
Doffer_Step_9_time(RESET := FALSE);
Doffer_Step := 0;
END_CASE

IF(M1500 = TRUE)THEN
MACHINE_STATUS := 1;
ELSIF (M1111 = TRUE) OR (M699 = TRUE) THEN
MACHINE_STATUS := 3;
ELSE
MACHINE_STATUS := 2;
END_IF

MC_SHIFT_REPORT.INPUT_PARAMETERS[80] := Pre_Voltage_avg;
MC_SHIFT_REPORT.INPUT_PARAMETERS[81] := Pre_Current_avg;
MC_SHIFT_REPORT.INPUT_PARAMETERS[91] := D920;
MC_SHIFT_REPORT.INPUT_PARAMETERS[83] := Pre_ActualData_Power_PFmeanT;
MC_SHIFT_REPORT.INPUT_PARAMETERS[84] :=	PRE_ActualData_ThdAngle_Freq;
MC_SHIFT_REPORT.INPUT_PARAMETERS[85] :=	PRE_Actual_Energy_Total;
MC_SHIFT_REPORT.INPUT_PARAMETERS[86] := PRE_ACTIVE_POWER_Total;
MC_SHIFT_REPORT.INPUT_PARAMETERS[87] :=	PRE_APPARENT_POWER_Total;
MC_SHIFT_REPORT.INPUT_PARAMETERS[88] :=	PRE_REACTIVE_POWER_Total;
MC_SHIFT_REPORT.INPUT_PARAMETERS[89] :=	PRE_APPARENT_Energy_Total;
MC_SHIFT_REPORT.INPUT_PARAMETERS[90] :=	PRE_REACTIVE_Energy_Total;
MC_SHIFT_REPORT.INPUT_PARAMETERS[93] :=	PRE_MACHINE_SPEED_MPM;
MC_SHIFT_REPORT.INPUT_PARAMETERS[92] := HMI_AIR_CONSUMPTION_SHIFT;

IF (gFl_Energy_Clear = TRUE) THEN
CUMMU_ENERGY := 0;
CUMMU_APP_ENERGY := 0;
CUMMU_REAC_ENERGY := 0;
PREVIOUS_ENERGY_TEMP := 0;
END_IF

IF ((DI_AIR_CONSUMPTION_CUMM >= DI_AIR_CONSUMPTION_CUMM_OLD)) THEN
AIR_CONSUMPTION_CUMM := (AIR_CONSUMPTION_CUMM + UINT_TO_REAL(DI_AIR_CONSUMPTION_CUMM - DI_AIR_CONSUMPTION_CUMM_OLD));
AIR_CONSUMPTION_SHIFT := (AIR_CONSUMPTION_SHIFT + UINT_TO_REAL(DI_AIR_CONSUMPTION_CUMM - DI_AIR_CONSUMPTION_CUMM_OLD));
ELSE
AIR_CONSUMPTION_CUMM := (AIR_CONSUMPTION_CUMM + UINT_TO_REAL(DI_AIR_CONSUMPTION_CUMM - DI_AIR_CONSUMPTION_CUMM_OLD + 65535) );
AIR_CONSUMPTION_SHIFT := (AIR_CONSUMPTION_SHIFT + UINT_TO_REAL(DI_AIR_CONSUMPTION_CUMM - DI_AIR_CONSUMPTION_CUMM_OLD + 65535));
END_IF

gFl_EnableRead :=TRUE;
gFl_Energy_Clear;
Vcurrent := ActualData.Rms.UrmsA;
Icurrent := ActualData.Rms.IrmsA;
Vcurrent_B := ActualData.Rms.UrmsB;
Icurrent_B := ActualData.Rms.IrmsB;
Vcurrent_C := ActualData.Rms.UrmsC;
Icurrent_C := ActualData.Rms.IrmsC;
Acurrent_A:=ActualData.ThdAngle.PAngleB;

IF EDGEPOS(calender_roller_piecing_v) AND M1500=FALSE THEN
calender_roller_piecing:=TRUE;
count:=count+1;
END_IF

IF calender_roller_piecing=TRUE AND count=2 THEN
calender_roller_piecing:=FALSE;
count:=0;
END_IF

CALIB:=0;
