IF(MC_SHIFT_CHANGE_RESET_POWER = 1)THEN
IF(AIR_CONSUMPTION_CUMM > 4000000) THEN
AIR_CONSUMPTION_CUMM := 0;
END_IF
Shift_Change_Temp_1 := 0;
